function makeAccount(balance) {
  return {
    withdraw(amount) {
      if (balance >= amount) { balance -= amount; return balance; }
      return 'Insufficient funds';
    },
    deposit(amount) { balance += amount; return balance; },
  };
}

const acc = makeAccount(50);
